/// <summary>
/// METCPIRepricingService
/// Service class responsible for executing CPI-driven Sales Order repricing.
/// Handles initialization, task contract binding, and processing of eligible orders into the repricing queue.
/// </summary>
class METCPIRepricingService extends METSysOperationService
{
    private guid topPickingProcessId;

}

Method.Source:
/// <summary>
/// Returns the name of the task service class used for CPI repricing.
/// </summary>
/// <returns>Task service class name.</returns>
protected str getTaskServiceClass()
{
    return classStr(METCPIRepricingTaskService);
}

/// <summary>
/// Returns the method name of the task service class to be executed.
/// </summary>
/// <returns>Task service class method name.</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METCPIRepricingTaskService, process);
}

/// <summary>
/// Returns the caption associated with the CPI repricing task service.
/// </summary>
/// <returns>Task service caption string.</returns>
protected str getTaskServiceCaption()
{
    return "@MET:CPISOPricing";
}

/// <summary>
/// Entry point for processing CPI repricing using the provided contract.
/// </summary>
/// <param name="_contract">Repricing data contract.</param>
public void process(METCPIRepricingContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Initializes global variables and triggers CPI repricing based on the contract query.
/// </summary>
public void initialise()
{
    super();

    METCPIRepricingContract contract = dataContract as METCPIRepricingContract;
    Query query = contract.initQuery();

    this.processCPIRepricing(query);
}

/// <summary>
/// Initializes the task data contract with process identifiers.
/// </summary>
/// <param name="_taskDataContract">Task data contract instance.</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METCPIRepricingContract contract = _taskDataContract as METCPIRepricingContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides a new instance of the CPI repricing task data contract.
/// </summary>
/// <returns>Task data contract object.</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METCPIRepricingContract();
}

/// <summary>
/// Executes CPI repricing by iterating through eligible Sales Orders from the query
/// and adding them to the repricing queue with retry handling for conflicts.
/// </summary>
/// <param name="_query">Query object defining eligible Sales Orders.</param>
void processCPIRepricing(Query _query)
{
    #OCCRetryCount

    METCPIRepricingQueue::cleanUpCPIRepricingQueue();
    RecordInsertList cpiRepricingQueueList = new RecordInsertList(tableNum(METCPIRepricingQueue));
    QueryRun queryRun = new QueryRun(_query);

    topPickingProcessId = newGuid();

    while (queryRun.next())
    {
        try
        {
            SalesTable salesTable = queryRun.get(tableNum(SalesTable));
            this.addToCPIRepricingQueueList(cpiRepricingQueueList, salesTable.SalesId);
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            // Catch errors so processing can continue
            curext();
        }
    }

    this.insertIntoTopPickingQueue(cpiRepricingQueueList);
}

/// <summary>
/// Adds a Sales Order record to the CPI repricing queue list.
/// </summary>
/// <param name="_cpiRepricingQueueList">RecordInsertList for CPI repricing queue.</param>
/// <param name="_salesId">Sales Order identifier.</param>
private void addToCPIRepricingQueueList(RecordInsertList _cpiRepricingQueueList, SalesId _salesId)
{
    METCPIRepricingQueue postRecord;
    postRecord.ProcessId = this.topPickingProcessId;
    postRecord.SalesId = _salesId;

    _cpiRepricingQueueList.add(postRecord);
}

/// <summary>
/// Performs bulk insert of Sales Orders into the CPI repricing queue table.
/// </summary>
/// <param name="_cpiRepricingQueueList">RecordInsertList containing Sales Orders to insert.</param>
private void insertIntoTopPickingQueue(RecordInsertList _cpiRepricingQueueList)
{
    _cpiRepricingQueueList.insertDatabase();
}
